for f in ['auc0.55_n20_prior1.0_binary.json','auc0.55_n50_prior1.0_binary.json','auc0.55_n100_prior1.0_binary.json','auc0.8_n20_prior1.0_binary.json','auc0.8_n50_prior1.0_binary.json']:
